// Test 2: Track D — payment_intent.succeeded with deposit metadata calls CONFIRM
it('[Track D] payment_intent.succeeded WITH deposit_transaction_id → CONFIRM_DEPOSIT_APPLICATION called + STRIPE_CHARGE_UPDATE_STATUS', async () => {
  const calledRpcs: string[] = []

  const sb = makeSupabaseMock(async (fn) => {
    calledRpcs.push(fn)
    return { data: { id: 'mock', status: 'applied' }, error: null }
  })

  const event = makePaymentIntentEvent('payment_intent.succeeded', {
    inkos_deposit_transaction_id: 'txn-deposit-001',
  })

  await processStripeEvent(event, sb)

  expect(calledRpcs).toContain(RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK)
  expect(calledRpcs).toContain(RPC.CONFIRM_DEPOSIT_APPLICATION)
})

// Test 3: Track D — payment_intent.payment_failed with deposit metadata calls ROLLBACK
it('[Track D] payment_intent.payment_failed WITH deposit_transaction_id → ROLLBACK with reason=payment_failed', async () => {
  const rollbackArgs: Record<string, unknown>[] = []

  const sb = makeSupabaseMock(async (fn, args) => {
    if (fn === RPC.ROLLBACK_DEPOSIT_APPLICATION) rollbackArgs.push(args)
    return { data: { id: 'mock' }, error: null }
  })

  const event = makePaymentIntentEvent('payment_intent.payment_failed', {
    inkos_deposit_transaction_id: 'txn-deposit-002',
  })

  await processStripeEvent(event, sb)

  expect(rollbackArgs).toHaveLength(1)
  expect(rollbackArgs[0]).toMatchObject({
    p_transaction_id: 'txn-deposit-002',
    p_reason: 'payment_failed',
  })
})

